23	    queryKey: ["feature_flags"],
24	    queryFn: async () => {
25	      const { data, error } = await supabase
26	        .from("feature_flags")
27	        .select("*")
28	        .order("key");
29	      if (error) throw error;
30	      return data as FeatureFlag[];
31	    },
32	    staleTime: 60_000,
33	  });
34	
35	  useEffect(() => {
36	    const channel = supabase
37	      .channel("feature_flags_realtime")
38	      .on(
39	        "postgres_changes",
40	        { event: "*", schema: "public", table: "feature_flags" },
41	        () => {
42	          qc.invalidateQueries({ queryKey: ["feature_flags"] });
43	        }
44	      )
45	      .subscribe();
46	
47	    return () => {
48	      supabase.removeChannel(channel);
49	    };
50	  }, [qc]);
